import re

from moler.exceptions import CommandFailure
from moler.exceptions import ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand

__author__ = 'Julia Patacz'
__copyright__ = 'Copyright (C) 2018, Nokia'
__email__ = 'julia.patacz@nokia.com'


class Discover(GenericEMSSIMCommand):
    """Discover command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Discover command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Discover, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return "discover"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_file_details(line)
                self._parse_xml_file(line)
                self._parse_key_value(line)
                self._parse_pddb_file(line)
                self._parse_build_id(line)
                self._parse_version(line)
                self._parse_success(line)
                self._parse_failure(line)
            except ParsingDone:
                pass
        return super(Discover, self).on_new_line(line, is_full_line)

    # 11:07:03          |  File details:
    _re_file_details = re.compile(r"File details:")

    def _parse_file_details(self, line):
        if self._regex_helper.search_compiled(Discover._re_file_details, line):
            if 'file_details' not in self.current_ret.keys():
                self.current_ret['file_details'] = {}
            raise ParsingDone

    # 11:07:03          |    fileId        => /bts//ram/CUPL_BTSA_BTS51.xml
    _re_key_value = re.compile(r"(?P<KEY>\S+)\s+=>\s+(?P<VALUE>\S+)$")

    def _parse_key_value(self, line):
        if self._regex_helper.search_compiled(Discover._re_key_value, line):
            temp_key = self._regex_helper.group('KEY')
            temp_value = self._regex_helper.group('VALUE')
            self.current_ret['file_details'][temp_key] = temp_value
            raise ParsingDone

    # 11:07:03          |  /home/fzp51/UPLOADS/CUPL_BTSA_BTS51.xml
    _re_xml_file = re.compile(r"(?P<PATH>[\/\S+]+\/UPLOADS\/\S+\.xml)")

    def _parse_xml_file(self, line):
        if self._regex_helper.search_compiled(Discover._re_xml_file, line):
            self.current_ret['xml_file_path'] = self._regex_helper.group('PATH')
            raise ParsingDone

    # 11:07:03          | /home/emssim/auto/ta_tools/emss/pddb/FLF18_1711_004_0.0.txt
    _re_pddb_file = re.compile(r"(?P<PATH>[\/\S+]+\/\S+\.txt)")

    def _parse_pddb_file(self, line):
        if self._regex_helper.search_compiled(Discover._re_pddb_file, line):
            self.current_ret['pddb_file_path'] = self._regex_helper.group('PATH')
            raise ParsingDone

    # 11:07:03          |Searching for pddb file based on build id: FLF18_ENB_0000_000325_000000
    _re_build_id = re.compile(r"build id:\s+(?P<BUILD_ID>\S+)$")

    def _parse_build_id(self, line):
        if self._regex_helper.search_compiled(Discover._re_build_id, line):
            self.current_ret['build_id'] = self._regex_helper.group('BUILD_ID')
            raise ParsingDone

    # 11:07:03          |Searching for pddb file based on version: FLF18
    _re_version = re.compile(r"version:\s+(?P<VERSION>\S+)$")

    def _parse_version(self, line):
        if self._regex_helper.search_compiled(Discover._re_version, line):
            self.current_ret['version'] = self._regex_helper.group('VERSION')
            raise ParsingDone

    # 11:07:05          |*** Discover Operation SUCCEEDED [Seq=15]
    _re_success = re.compile(r"Discover (NE Flow|Operation) SUCCEEDED")

    def _parse_success(self, line):
        if self._regex_helper.search_compiled(Discover._re_success, line):
            self.current_ret['discover_status'] = "SUCCESS"
            raise ParsingDone

    # 07:56:56         *|WARNING: Send failed: eNodeB socket is closed
    _re_failure = re.compile(r"failed:\s+(?P<FAILURE>.*)$")

    def _parse_failure(self, line):
        if self._regex_helper.search_compiled(Discover._re_failure, line):
            self.set_exception(CommandFailure(self, f"command failed in line '{line}'"))


